export const rewardItems = import.meta.env.VITE_REWARD_PREVIEW === 'true' ? previewRewardItems : liveRewardItems

// Colour swatches for the colour picker. Unknown colours get a neutral grey.
const swatchColors = { Black: '#1f1f1f', Pink: '#f28cb8', Blue: '#2f6fd0', Green: '#2e8b3e', Yellow: '#f5c518' }

// Items with a colour are shown as ONE product card. Each colour keeps its own id, photo and redemption count.
export function groupRewardProducts(items) {
  const groups = new Map()
  for (const item of items) {
    const key = item.group || (item.color ? ['group', item.category, item.brand || '', item.name].join('|') : item.id)
    if (!groups.has(key)) groups.set(key, { key, name: item.name, brand: item.brand ?? null, category: item.category, description: item.description || '', variants: [] })
    groups.get(key).variants.push({ ...item, label: item.color || item.design || '', swatch: item.swatch || (item.color ? (swatchColors[item.color] || '#bdb3aa') : null) })
  }
  return [...groups.values()].map(product => {
    const priced = product.variants.map(v => v.points).filter(p => Number.isSafeInteger(p) && p > 0)
    const first = product.variants[0]
    return { ...product, image: first.image, imageAlt: first.imageAlt, variantLabel: first.design ? 'Design' : 'Color', points: priced.length ? Math.min(...priced) : null, available: product.variants.some(v => v.available) }
  })
}
export const rewardProducts = groupRewardProducts(rewardItems)

export function productCostText(product) {
  const priced = product.variants.map(v => v.points).filter(p => Number.isSafeInteger(p) && p > 0)
  if (!priced.length) return 'Aurels cost to be confirmed'
  const min = Math.min(...priced), max = Math.max(...priced)
  return min === max ? `${min.toLocaleString()} Aurels` : `From ${min.toLocaleString()} Aurels`
}
export function selectRewards(items, brand = 'all', sort = 'points-asc', category = 'all') {
  return items.filter(item => (brand === 'all' || item.brand === brand) && (category === 'all' || item.category === category)).slice().sort((a,b) => {
    const aKnown = Number.isFinite(a.points), bKnown = Number.isFinite(b.points)
    if (aKnown !== bKnown) return aKnown ? -1 : 1
    if (sort === 'name') return a.name.localeCompare(b.name)
    return (aKnown ? (a.points - b.points) * (sort === 'points-desc' ? -1 : 1) : 0) || a.name.localeCompare(b.name)
  })
}

export const standardRewardSizes = ['S', 'M', 'L', 'XL']
export function getRewardSizes(item) {
  if (Array.isArray(item.sizes) && item.sizes.length) return [...new Set(item.sizes.filter(size => typeof size === 'string' && size.trim()))]
  return ['apparel', 'womens'].includes(item.category) ? standardRewardSizes : []
}

